INSERT OR IGNORE INTO lessons (id,created_at,updated_at,day,position,title_ja,title_en,summary_ja,summary_en,status) VALUES ('LS-007','2026-10-04T11:50:04.465185Z','2026-10-04T11:50:04.465185Z',1,7,'写真とSNSの扱い','Photos and social media','撮らない、載せない、話さない。','No photos, no posts, no stories.','draft');
INSERT OR IGNORE INTO lessons (id,created_at,updated_at,day,position,title_ja,title_en,summary_ja,summary_en,status) VALUES ('LS-008','2026-10-04T11:50:04.465185Z','2026-10-04T11:50:04.465185Z',1,8,'秘書、警護、ファミリーオフィスとの連携','Working with assistants, security and family offices','誰の指示に従い、誰に報告するか。','Whose instructions to follow and whom to report to.','draft');
