INSERT OR IGNORE INTO lessons (id,created_at,updated_at,day,position,title_ja,title_en,summary_ja,summary_en,status) VALUES ('LS-018','2026-10-04T11:50:04.465185Z','2026-10-04T11:50:04.465185Z',2,18,'翻訳アプリの正しい使い方','Using translation apps properly','短い文、画面で確認、機密は入力しない。','Short sentences, confirm on screen, never type confidential details.','draft');
INSERT OR IGNORE INTO lessons (id,created_at,updated_at,day,position,title_ja,title_en,summary_ja,summary_en,status) VALUES ('LS-019','2026-10-04T11:50:04.465185Z','2026-10-04T11:50:04.465185Z',2,19,'確認・遅れ・お詫びのメッセージ','Writing confirmation, delay and apology messages','短く、正確に、次の行動を書く。','Short, precise, with the next step.','draft');
INSERT OR IGNORE INTO exam_questions (id,created_at,updated_at,position,q_ja,q_en,options_ja,options_en,correct,explain_ja,explain_en) VALUES ('Q-001','2026-10-04T11:50:04.465185Z','2026-10-04T11:50:04.465185Z',1,'警護が必要なVIPを空港で出迎えるとき、ネームボードに書くものとして最も適切なのは？','When meeting a VIP who needs security at the airport, what should the name board show?','["お客さまのフルネームを大きく", "事前に秘書と決めた仮の名前や合図", "会社のロゴだけ", "何も持たずに声で呼ぶ"]','["The client''s full name in large letters", "A code name or signal agreed in advance with the assistant", "Only the company logo", "Nothing; call out the name"]',1,'本名を掲げると所在が知られてしまいます。合図は事前に決めます。','A real name reveals the client''s whereabouts. Agree the signal in advance.');
INSERT OR IGNORE INTO exam_questions (id,created_at,updated_at,position,q_ja,q_en,options_ja,options_en,correct,explain_ja,explain_en) VALUES ('Q-002','2026-10-04T11:50:04.465185Z','2026-10-04T11:50:04.465185Z',2,'後部座席のどこにお客さまが座るか分からないとき、最も確実な方法は？','If you are unsure where the client will sit, what is the most reliable approach?','["日本の上座の決まりに従う", "お客さまに乗車してから聞く", "事前に秘書や手配者に確認しておく", "助手席を勧める"]','["Follow Japanese seating etiquette", "Ask once the client is in the car", "Confirm in advance with the assistant or booker", "Offer the front passenger seat"]',2,'国や警護の方針で席は変わります。前もって確認します。','Seating depends on culture and security. Confirm beforehand.');
INSERT OR IGNORE INTO exam_questions (id,created_at,updated_at,position,q_ja,q_en,options_ja,options_en,correct,explain_ja,explain_en) VALUES ('Q-003','2026-10-04T11:50:04.465185Z','2026-10-04T11:50:04.465185Z',3,'お客さまが車内で電話や作業をしているとき、乗務員がすべきことは？','The client is on the phone or working in the car. What should the driver do?','["気をつかって話しかける", "ラジオをつける", "話しかけず、必要な連絡は短くまとめる", "到着まで一切何も伝えない"]','["Make polite conversation", "Turn on the radio", "Stay silent and keep any necessary updates short", "Say nothing at all until arrival"]',2,'静かな環境を守り、必要な情報だけを短く伝えます。','Protect the quiet; give only necessary information, briefly.');
INSERT OR IGNORE INTO exam_questions (id,created_at,updated_at,position,q_ja,q_en,options_ja,options_en,correct,explain_ja,explain_en) VALUES ('Q-004','2026-10-04T11:50:04.465185Z','2026-10-04T11:50:04.465185Z',4,'車内で聞いた会話の内容について正しいのは？','What is correct about conversations you hear in the car?','["同僚になら話してよい", "家族になら話してよい", "誰にも話さない", "名前を伏せればSNSに書いてよい"]','["You may tell colleagues", "You may tell your family", "You tell no one", "You may post it without names"]',2,'家族、同僚、SNSを含め、誰にも話しません。','No one: not family, not colleagues, not social media.');
INSERT OR IGNORE INTO exam_questions (id,created_at,updated_at,position,q_ja,q_en,options_ja,options_en,correct,explain_ja,explain_en) VALUES ('Q-005','2026-10-04T11:50:04.465185Z','2026-10-04T11:50:04.465185Z',5,'お客さまや車両の写真をSNSに投稿することについて正しいのは？','What is correct about posting photos of clients or the vehicle on social media?','["お客さまが写っていなければよい", "仕事が終わってからならよい", "投稿しない", "位置情報を消せばよい"]','["Fine if the client is not visible", "Fine once the job is over", "Do not post", "Fine if location data is removed"]',2,'車両や場所からもお客さまが特定されます。投稿しません。','The car or place can identify the client. Do not post.');
INSERT OR IGNORE INTO exam_questions (id,created_at,updated_at,position,q_ja,q_en,options_ja,options_en,correct,explain_ja,explain_en) VALUES ('Q-006','2026-10-04T11:50:04.465185Z','2026-10-04T11:50:04.465185Z',6,'有名人のお客さまを乗せたとき、してはいけないことは？','With a famous client on board, what must you never do?','["行き先を確認する", "サインや写真をお願いする", "ドアを開ける", "温度の好みを聞く"]','["Confirm the destination", "Ask for an autograph or photo", "Open the door", "Ask about temperature"]',1,'お客さまはプライベートな時間を過ごしています。','The client is in private time.');
INSERT OR IGNORE INTO exam_questions (id,created_at,updated_at,position,q_ja,q_en,options_ja,options_en,correct,explain_ja,explain_en) VALUES ('Q-007','2026-10-04T11:50:04.465185Z','2026-10-04T11:50:04.465185Z',7,'警護チームがいる場合の正しい行動は？','With a security team present, what is the correct behaviour?','["渋滞を見て自分の判断でルートを変える", "打ち合わせたルートと警護責任者の指示に従う", "警護より先に車を降りてドアを開ける", "お客さまの指示だけに従う"]','["Change route on your own judgement in traffic", "Follow the agreed route and the security lead''s instructions", "Get out before security and open the door", "Follow only the client''s instructions"]',1,'変更は警護責任者と調整してから行います。','Any change is coordinated with the security lead first.');
INSERT OR IGNORE INTO exam_questions (id,created_at,updated_at,position,q_ja,q_en,options_ja,options_en,correct,explain_ja,explain_en) VALUES ('Q-008','2026-10-04T11:50:04.465185Z','2026-10-04T11:50:04.465185Z',8,'秘書から乗務中に行程の変更を頼まれたとき、まずすべきことは？','During the job, the assistant asks you to change the itinerary. What do you do first?','["そのまま変更する", "断る", "自社の配車担当（運行管理者）に連絡して確認する", "お客さまに直接確認する"]','["Change it straight away", "Refuse", "Contact your company''s dispatcher to confirm", "Ask the client directly"]',2,'乗務員は会社の指示で動きます。変更は配車担当が確認します。','Drivers work under their company''s instructions; dispatch confirms changes.');
INSERT OR IGNORE INTO exam_questions (id,created_at,updated_at,position,q_ja,q_en,options_ja,options_en,correct,explain_ja,explain_en) VALUES ('Q-009','2026-10-04T11:50:04.465185Z','2026-10-04T11:50:04.465185Z',9,'お迎えに遅れそうなとき、正しい連絡の仕方は？','You may be late for a pickup. How do you communicate?','["遅れが確定してから連絡する", "分かった時点ですぐ、到着見込み時刻とともに連絡する", "到着してから謝る", "連絡はせず急いで向かう"]','["Contact once the delay is certain", "Contact immediately, with a new arrival time", "Apologise on arrival", "Do not call; just hurry"]',1,'早く、具体的な時刻とともに伝えます。','Early, with a specific time.');
INSERT OR IGNORE INTO exam_questions (id,created_at,updated_at,position,q_ja,q_en,options_ja,options_en,correct,explain_ja,explain_en) VALUES ('Q-010','2026-10-04T11:50:04.465185Z','2026-10-04T11:50:04.465185Z',10,'お詫びのメッセージに必ず入れるべきものは？','What must an apology message always include?','["長い理由の説明", "謝罪、新しい到着予定時刻、次の行動", "会社のPR", "絵文字"]','["A long explanation", "Apology, new arrival time and next step", "Company promotion", "Emoji"]',1,'短く、正確に、次に何をするかを書きます。','Short, precise, and what happens next.');
INSERT OR IGNORE INTO exam_questions (id,created_at,updated_at,position,q_ja,q_en,options_ja,options_en,correct,explain_ja,explain_en) VALUES ('Q-011','2026-10-04T11:50:04.465185Z','2026-10-04T11:50:04.465185Z',11,'身だしなみとして避けるべきものは？','What should a driver avoid in grooming?','["清潔な制服", "整えた髪", "強い香水や柔軟剤の香り", "磨いた靴"]','["A clean uniform", "Neat hair", "Strong perfume or fabric softener scent", "Polished shoes"]',2,'車内は無臭が基本です。','The cabin should be scent-free.');
INSERT OR IGNORE INTO exam_questions (id,created_at,updated_at,position,q_ja,q_en,options_ja,options_en,correct,explain_ja,explain_en) VALUES ('Q-012','2026-10-04T11:50:04.465185Z','2026-10-04T11:50:04.465185Z',12,'車内の温度はどう決める？','How should cabin temperature be set?','["乗務員が快適な温度", "乗車後に毎回聞く", "事前に確認した好みに合わせ、乗車前に整えておく", "季節に関係なく22度"]','["Whatever suits the driver", "Ask every time after boarding", "Set in advance to the preference confirmed beforehand", "Always 22°C"]',2,'乗った瞬間に快適であることが理想です。','Comfortable from the moment they step in.');
INSERT OR IGNORE INTO exam_questions (id,created_at,updated_at,position,q_ja,q_en,options_ja,options_en,correct,explain_ja,explain_en) VALUES ('Q-013','2026-10-04T11:50:04.465185Z','2026-10-04T11:50:04.465185Z',13,'出発前の車内準備として最も適切なのは？','What is the best preparation before departure?','["前のお客さまの忘れ物をそのまま置いておく", "水、充電ケーブル、ティッシュをそろえ、清潔で無臭にしておく", "芳香剤を強めにする", "仕事の書類を後部座席に置く"]','["Leave the previous client''s items", "Water, charging cables, tissues ready; clean and scent-free", "Use a strong air freshener", "Keep paperwork on the rear seat"]',1,NULL,NULL);
INSERT OR IGNORE INTO exam_questions (id,created_at,updated_at,position,q_ja,q_en,options_ja,options_en,correct,explain_ja,explain_en) VALUES ('Q-014','2026-10-04T11:50:04.465185Z','2026-10-04T11:50:04.465185Z',14,'荷物の扱いとして正しいのは？','What is correct when handling luggage?','["お客さまに自分で積んでもらう", "乗務員が積み下ろしし、手元に置きたいバッグは本人に確認する", "すべてトランクに入れる", "警護に任せる"]','["Let the client load it", "The driver loads it and asks which bag the client wants to keep", "Put everything in the boot", "Leave it to security"]',1,'貴重品のバッグは手元に置きたいことが多いです。','Clients often keep valuables with them.');
INSERT OR IGNORE INTO exam_questions (id,created_at,updated_at,position,q_ja,q_en,options_ja,options_en,correct,explain_ja,explain_en) VALUES ('Q-015','2026-10-04T11:50:04.465185Z','2026-10-04T11:50:04.465185Z',15,'ドアを開けるタイミングとして正しいのは？','When should you open the door?','["停車する前に準備のため開ける", "停車し、安全を確認してから外に回って開ける", "お客さまが自分で開けるのを待つ", "車内からロックだけ外す"]','["Before stopping, to be ready", "After stopping and checking it is safe, walk round and open it", "Wait for the client to open it", "Just unlock from inside"]',1,NULL,NULL);
INSERT OR IGNORE INTO exam_questions (id,created_at,updated_at,position,q_ja,q_en,options_ja,options_en,correct,explain_ja,explain_en) VALUES ('Q-016','2026-10-04T11:50:04.465185Z','2026-10-04T11:50:04.465185Z',16,'待機中の正しい過ごし方は？','What is correct while waiting?','["正面玄関の前に停め続ける", "目立たない場所で、すぐ出られる状態で連絡に即応できるようにする", "車を離れて食事をする", "エンジンを切って仮眠する"]','["Stay parked at the main entrance", "Wait discreetly, ready to move, reachable at once", "Leave the car to eat", "Switch off and nap"]',1,NULL,NULL);
INSERT OR IGNORE INTO exam_questions (id,created_at,updated_at,position,q_ja,q_en,options_ja,options_en,correct,explain_ja,explain_en) VALUES ('Q-017','2026-10-04T11:50:04.465185Z','2026-10-04T11:50:04.465185Z',17,'中東からのお客さまを担当するとき、事前に確認しておくとよいことは？','Before serving clients from the Middle East, what is useful to confirm?','["好きなサッカーチーム", "お祈りの時間や食事、男女の同乗などの習慣", "日本語が話せるか", "チップの金額"]','["Favourite football team", "Prayer times, food, and customs such as mixed seating", "Whether they speak Japanese", "Tip amounts"]',1,'宗教と習慣への配慮は、事前の確認から始まります。','Respect for religion and custom starts with asking in advance.');
INSERT OR IGNORE INTO exam_questions (id,created_at,updated_at,position,q_ja,q_en,options_ja,options_en,correct,explain_ja,explain_en) VALUES ('Q-018','2026-10-04T11:50:04.465185Z','2026-10-04T11:50:04.465185Z',18,'お客さまからチップを差し出されたときは？','A client offers you a tip. What do you do?','["必ず受け取る", "必ず断って理由を説明しない", "会社の規程に従って丁寧に対応する", "金額が少なければ断る"]','["Always accept", "Always refuse without explanation", "Respond politely according to company rules", "Refuse if it is small"]',2,NULL,NULL);
INSERT OR IGNORE INTO exam_questions (id,created_at,updated_at,position,q_ja,q_en,options_ja,options_en,correct,explain_ja,explain_en) VALUES ('Q-019','2026-10-04T11:50:04.465185Z','2026-10-04T11:50:04.465185Z',19,'乗車中にお客さまの体調が急に悪くなったときは？','The client suddenly feels unwell during the ride. What do you do?','["急いで目的地へ向かう", "安全な場所に停車し、必要なら119番に連絡し、秘書と会社に知らせる", "窓を開けて様子を見る", "お客さまの判断を待つ"]','["Hurry to the destination", "Stop safely, call 119 if needed, inform the assistant and your company", "Open the window and wait", "Wait for the client to decide"]',1,NULL,NULL);
INSERT OR IGNORE INTO exam_questions (id,created_at,updated_at,position,q_ja,q_en,options_ja,options_en,correct,explain_ja,explain_en) VALUES ('Q-020','2026-10-04T11:50:04.465185Z','2026-10-04T11:50:04.465185Z',20,'翻訳アプリの使い方として正しいのは？','What is correct about translation apps?','["長い文をまとめて入力する", "短い文で使い、住所や時刻など大事な内容は画面を見せて確認する", "お客さまの名前や行き先を詳しく入力する", "使わないほうがよい"]','["Type long passages at once", "Use short sentences and show the screen to confirm key details", "Enter the client''s name and destinations in full", "Better not to use them"]',1,'機密になる情報は入力しません。','Never type confidential information.');
INSERT OR IGNORE INTO exam_questions (id,created_at,updated_at,position,q_ja,q_en,options_ja,options_en,correct,explain_ja,explain_en) VALUES ('Q-021','2026-10-04T11:50:04.465185Z','2026-10-04T11:50:04.465185Z',21,'到着予定を伝える英語として最も適切なのは？','Which English sentence best gives the arrival time?','["We arrive maybe 7:15.", "We will arrive at your hotel at around 7:15.", "Hotel 7:15 OK?", "You will arrive later."]','["We arrive maybe 7:15.", "We will arrive at your hotel at around 7:15.", "Hotel 7:15 OK?", "You will arrive later."]',1,NULL,NULL);
INSERT OR IGNORE INTO exam_questions (id,created_at,updated_at,position,q_ja,q_en,options_ja,options_en,correct,explain_ja,explain_en) VALUES ('Q-022','2026-10-04T11:50:04.465185Z','2026-10-04T11:50:04.465185Z',22,'次の行き先を丁寧に確認する英語は？','Which is the polite way to confirm the next destination?','["Where you go?", "Next where?", "May I confirm your next destination?", "Tell me the place."]','["Where you go?", "Next where?", "May I confirm your next destination?", "Tell me the place."]',2,NULL,NULL);
INSERT OR IGNORE INTO exam_questions (id,created_at,updated_at,position,q_ja,q_en,options_ja,options_en,correct,explain_ja,explain_en) VALUES ('Q-023','2026-10-04T11:50:04.465185Z','2026-10-04T11:50:04.465185Z',23,'お客さまの言ったことが聞き取れなかったときは？','You did not understand what the client said. What do you do?','["推測して動く", "うなずいてごまかす", "短い言葉で聞き直すか、書いてもらうか、画面で確認する", "秘書が来るまで待つ"]','["Guess and act", "Nod and move on", "Ask again simply, ask them to write it, or confirm on a screen", "Wait for the assistant"]',2,NULL,NULL);
INSERT OR IGNORE INTO exam_questions (id,created_at,updated_at,position,q_ja,q_en,options_ja,options_en,correct,explain_ja,explain_en) VALUES ('Q-024','2026-10-04T11:50:04.465185Z','2026-10-04T11:50:04.465185Z',24,'秘密保持の義務はいつまで続く？','How long does the duty of confidentiality last?','["その日の乗務が終わるまで", "契約で定めた範囲は、乗務の後も続く", "1か月", "会社を辞めるまで"]','["Until the end of that day''s job", "As set in the agreement, it continues after the job", "One month", "Until you leave the company"]',1,NULL,NULL);
INSERT OR IGNORE INTO exam_questions (id,created_at,updated_at,position,q_ja,q_en,options_ja,options_en,correct,explain_ja,explain_en) VALUES ('Q-025','2026-10-04T11:50:04.465185Z','2026-10-04T11:50:04.465185Z',25,'お客さまから個人の連絡先を聞かれたときは？','The client asks for your personal contact details. What do you do?','["個人の電話番号を教える", "会社の連絡先を伝え、ご依頼は会社を通していただく", "SNSのアカウントを教える", "黙って答えない"]','["Give your personal number", "Give the company''s contact; bookings go through the company", "Give your social media account", "Say nothing"]',1,'ご依頼は必ず会社を通します。','All bookings go through the company.');
